db.pedidos.insertOne({
  cliente_id: ObjectId("..."),          // REFERENCIA: cliente vive alem do pedido
  data: new Date("2026-09-09T10:00:00Z"),
  endereco_entrega: {                   // ANINHADO: e uma copia historica
    logradouro: "SQN 210 Bloco B",
    cidade: "Brasília", uf: "DF", cep: "70862-020"
  },
  itens: [                              // ANINHADO: nao existe fora do pedido
    { produto: "Teclado", quantidade: 1, preco_unitario: 250.00 },
    { produto: "Monitor", quantidade: 2, preco_unitario: 899.90 }
  ],
  total: 2049.80
});

db.pedidos.aggregate([
  { $match: {                                    // 1. WHERE: cedo, corta volume e usa indice
      "endereco_entrega.cidade": "Brasília",
      data: { $gte: new Date("2026-01-01"), $lt: new Date("2027-01-01") }
  } },
  { $unwind: "$itens" },                         // 2. um documento por item
  { $group: {                                    // 3. agrupa pelo produto
      _id: "$itens.produto",
      receita: { $sum: { $multiply: ["$itens.quantidade", "$itens.preco_unitario"] } },
      unidades: { $sum: "$itens.quantidade" }
  } },
  { $sort: { receita: -1 } },
  { $limit: 3 }
]);

// diagnostico
db.pedidos.find({ status: "entregue" }).sort({ data: -1 }).limit(20)
  .explain("executionStats");
// stage: SORT  <- ordenacao em memoria, apos buscar todos os "entregue"

// correcao
db.pedidos.createIndex({ status: 1, data: -1 });

// depois: o SORT desaparece, totalDocsExamined cai para ~20

