// Fluxo proposto — a verdade em um lugar so, indice derivado e reconstruivel

   aplicacao
       |
       v  escrita confirmada (write concern majority)
   [ MongoDB ]  <-- fonte da verdade
       |
       v  change stream (ou CDC)
   [ pipeline de sincronizacao ]  <-- reexecutavel do zero
       |
       v  bulk
   [ Elasticsearch ]  <-- indice derivado, descartavel

// reconstrucao completa deve ser um procedimento normal, nao uma emergencia:
//   1. cria indice novo com o mapping atualizado
//   2. reindexa a partir do MongoDB
//   3. troca o alias para o indice novo
//   4. remove o antigo

// 1. diagnostico: os tokens preservam o acento
POST _analyze
{ "analyzer": "standard", "text": "São Paulo" }
// -> [ "são", "paulo" ]     e "sao" nunca casa com "são"

// 2. correcao: analyzer com asciifolding, aplicado na indexacao e na busca
PUT cidades
{
  "settings": { "analysis": { "analyzer": {
    "pt_sem_acento": {
      "tokenizer": "standard",
      "filter": [ "lowercase", "asciifolding" ]
    }
  } } },
  "mappings": { "properties": {
    "nome": {
      "type": "text",
      "analyzer": "pt_sem_acento",
      "fields": { "keyword": { "type": "keyword", "ignore_above": 256 } }
    }
  } }
}

// 3. verificacao
POST cidades/_analyze
{ "field": "nome", "text": "São Paulo" }   // -> [ "sao", "paulo" ]

